let meta = {};
try { meta = $('Set Hardcoded URL').first().json; } catch(e) {}
try { if (!meta.url) meta = $('Form Trigger').first().json; } catch(e) {}
try { if (!meta.url) meta = $('Set Thesis URL').first().json; } catch(e) {}

const raw = $input.first().json;
const html = raw.html || raw.data || raw.body || raw.content || '';

const toHex = (r, g, b) =>
  '#' + [r, g, b].map(x => parseInt(x).toString(16).padStart(2, '0')).join('');

// --- Extract brand palette (exclude black/white) ---
const colorCounts = {};
let m;
const rgbaRegex2 = /rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*[\d.]+)?\)/g;
while ((m = rgbaRegex2.exec(html)) !== null) {
  const hex = toHex(m[1], m[2], m[3]);
  if (['#000000','#ffffff','#000'].includes(hex)) continue;
  colorCounts[hex] = (colorCounts[hex] || 0) + 1;
}
const hexRegex = /#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})(?![A-Fa-f0-9])/g;
while ((m = hexRegex.exec(html)) !== null) {
  const hex = m[0].toLowerCase();
  if (['#000000','#ffffff','#000','#fff'].includes(hex)) continue;
  colorCounts[hex] = (colorCounts[hex] || 0) + 1;
}

const sortedColors = Object.entries(colorCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(e => e[0]);

// --- Detect background color ---
let bgColor = null;

// 1. Check body inline style: <body style="background-color:..."> or background:...
const bodyInline = html.match(/<body[^>]+style=["'][^"']*background(?:-color)?\s*:\s*([^;"'\s]+)/i);
if (bodyInline) bgColor = bodyInline[1].toLowerCase();

// 2. Check <style> blocks for body { background... }
if (!bgColor) {
  const styleBlocks = [];
  const styleRe = /<style[^>]*>([\s\S]*?)<\/style>/gi;
  let sm;
  while ((sm = styleRe.exec(html)) !== null) styleBlocks.push(sm[1]);
  const styleText = styleBlocks.join('\n');
  const bodyBgRe = /body\s*\{[^}]*background(?:-color)?\s*:\s*([^;}\/]+)/i;
  const bm = styleText.match(bodyBgRe);
  if (bm) bgColor = bm[1].trim().toLowerCase();
}

// Normalize common color names
const namedColors = { white: '#ffffff', black: '#000000', transparent: 'transparent' };
if (bgColor && namedColors[bgColor]) bgColor = namedColors[bgColor];

const bgLabel = bgColor
  ? bgColor === '#ffffff' ? '#ffffff (white)'
  : bgColor === '#000000' ? '#000000 (black)'
  : bgColor === 'transparent' ? 'transparent'
  : bgColor
  : 'not detected';

// --- Build email ---
const labels = ['Primary', 'Secondary', 'Color 3', 'Color 4', 'Color 5'];
const rows = sortedColors.map((hex, i) =>
  '<tr>' +
  '<td style="padding:10px 16px 10px 0;font-family:sans-serif;font-weight:bold;">' + labels[i] + '</td>' +
  '<td style="padding:10px 12px;">' +
    '<span style="display:inline-block;width:72px;height:36px;background:' + hex + ';border:1px solid #ddd;border-radius:4px;"></span>' +
  '</td>' +
  '<td style="padding:10px 0;font-family:monospace;font-size:14px;">' + hex + '</td>' +
  '</tr>'
).join('');

const bgSwatch = bgColor && bgColor !== 'transparent' && bgColor !== 'not detected'
  ? '<span style="display:inline-block;width:72px;height:36px;background:' + bgColor + ';border:1px solid #ddd;border-radius:4px;margin-right:12px;"></span>'
  : '';

const emailHtml =
  '<div style="font-family:sans-serif;max-width:500px;">' +
  '<h2 style="margin-bottom:4px;">Brand Palette</h2>' +
  '<p style="color:#666;margin-top:0;">Extracted from <a href="' + meta.url + '">' + meta.url + '</a></p>' +
  '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;">' +
  rows +
  '</table>' +
  '<hr style="margin:16px 0;border:none;border-top:1px solid #eee;">' +
  '<p style="margin:0 0 6px;"><strong>Background:</strong></p>' +
  '<p style="margin:0;font-family:monospace;font-size:14px;display:flex;align-items:center;gap:12px;">' +
  bgSwatch + bgLabel +
  '</p>' +
  '</div>';

return [{ json: {
  url: meta.url || 'unknown',
  email: meta.email || 'unknown',
  primary: sortedColors[0] || null,
  secondary: sortedColors[1] || null,
  palette: sortedColors,
  background: bgColor || 'not detected',
  emailHtml
} }];
